function report=studyRocketRiemannReservoirNewton(folder,probeFile)
%STUDYROCKETRIEMANNRESERVOIRNEWTON 在显式新储库边界下开始独立的真实原NS修正历史。
% 模块一：同Q新基线与探针完全绑定，旧13接受/258调用只作来源，不拼进新问题。
% 模块二：原NS初猜检查及总方向均重新求差分；线预条件不替代完整NS验收。
% 模块三：保留原0.1、正性、80—2000K、下降、空间/稳态/边界门槛和完整候选。
root=fileparts(fileparts(mfilename('fullpath')));addpath(root,fullfile(root,'internalFlow'));setupCutCellFlow;
assert(~exist(folder,'dir'));mkdir(folder);
baseFile=fullfile(root,'outputs','v83_validation','riemannreservoirreal01','riemann_reservoir_real_evidence.mat');s=load(baseFile,'Q','rate','info','gas','boundary','scale');
d=load(fullfile(root,'outputs','v80_validation','domain02','shell_domain_evidence.mat'),'domain');gas=s.gas;boundary=s.boundary;
options=struct('linearEquation','steady-newton','normalEulerLinearization','exact-branch','jacobianAction','original-difference', ...
    'residualScale',s.scale,'maximumIterations',1,'initialPseudoDt',1e-7,'maximumKrylovIterations',48,'linearRelativeTolerance',.1, ...
    'maximumStepRetries',0,'maximumLineSearch',16,'steadyInitialGuess',struct('file',probeFile,'variant','ns-probe','scale',1));
timer=tic;result=solveRocketShellSteadyKrylov(s.Q,d.domain,gas,boundary,options);elapsed=toc(timer);
assert(isequaln(result.initialRate,s.rate)&&isequaln(result.initialInfo,s.info));mapped=mapCutCellWallFields(d.domain,result.info,false);
lineage=struct('sourceState','krylov19-state-only-explicit-new-Riemann-reservoir-boundary', ...
    'sourceHistoryAppended',false,'newBoundaryProblemInitialCounter',0,'previousProblemAcceptancesNotAppended',13,'previousProblemNSNotAppended',258, ...
    'externalCFDImported',false,'interiorEulerFlux','exact-godunov','wallVelocityGradient','dirichlet-tangent');
displayHistory=result.history;
report=struct('status','bounded-real-20deg-new-explicit-reservoir-boundary-NS-Newton-separate-history', ...
    'sourceFaces',size(d.domain.inputGeometry.F,1),'cellCount',size(result.Q,1),'acceptedNonlinearIterations',result.acceptedNonlinearIterations, ...
    'priorAcceptedNonlinearIterations',0,'totalNewEquationAcceptedIterations',result.acceptedNonlinearIterations, ...
    'candidateTrials',result.candidateTrials,'residualEvaluations',result.residualEvaluations,'totalNewEquationResidualEvaluations',result.residualEvaluations, ...
    'initialMaximumResidual',result.initialMaximumResidual,'maximumResidual',result.maximumResidual,'initialRmsMerit',result.initialRmsMerit,'rmsMerit',result.rmsMerit, ...
    'elapsedSeconds',elapsed,'steadyConverged',result.steadyConverged,'stopReason',result.stopReason, ...
    'spatialConservationRelative',result.spatialConservationRelative,'steadyBoundaryFluxBalance',result.steadyBoundaryFluxBalance, ...
    'signedHeatPowerW',mapped.summedKnownHeatPower,'wallHeatRangeWm2',[min(mapped.heatFluxIntoWall.value) max(mapped.heatFluxIntoWall.value)], ...
    'lineage',lineage,'wallVelocityGradient','dirichlet-tangent','openBoundaryDiscretization','exact-Riemann-reservoir', ...
    'sameEquationHistoryContinued',false,'sourceHistoryAppended',false,'steadyInitialGuessReport',result.steadyInitialGuessReport, ...
    'steadyInitialGuessModelApplications',result.steadyInitialGuessModelApplications,'physicalTimeAdvanced',0,'BETimeStepsClaimed',0, ...
    'physicalSolution',false,'newProductionSolvedAreaM2',0,'engineProcessID',feature('getpid'));
save(fullfile(folder,'wall_velocity_krylov_evidence.mat'),'result','report','mapped','gas','boundary','lineage','displayHistory','-v7');
fid=fopen(fullfile(folder,'wall_velocity_krylov_summary.json'),'w','n','UTF-8');assert(fid>=0);guard=onCleanup(@()fclose(fid));fprintf(fid,'%s',jsonencode(report));fprintf('%s\n',jsonencode(report));
end
